      "keystrokes": "python3 -c '
import json

with open("input.json", "r", encoding="utf-8") as f:
    data = json.load(f)

markers = [r for r in data if r["id"].startswith("marker_")]
marker_sum = sum(r["value"] for r in markers)

group_max = {}
for r in data:
    group = r["group"]
    if group not in group_max or r["value"] > group_max[group]:
        group_max[group] = r["value"]

output = {
    "marker_sum": marker_sum,
    "markers": markers,
    "group_max": group_max,
    "marker_notes": [r["note"] for r in markers]
}

with open("output.json", "w", encoding="utf-8") as f:
    json.dump(output, f, indent=2, ensure_ascii=False)

lines = ["Benchmark Summary", "=================", ""]
lines.append(f"Total marker records: {len(markers)}")
lines.append(f"Sum of marker values: {marker_sum}")
lines.append("")
lines.append("Marker Details:")
for m in markers:
    lines.append(f"  - {m[chr(105)+chr(100)]}: group={m[chr(103)+chr(114)+chr(111)+chr(117)+chr(112)]}, value={m[chr(118)+chr(97)+chr(108)+chr(117)+chr(101)]}, note={m[chr(110)+chr(111)+chr(116)+chr(101)]}")
lines.append("")
lines.append("Per-Group Maximum Values:")
for g in sorted(group_max.keys()):
    lines.append(f"  - {g}: {group_max[g]}")

with open("summary.txt", "w", encoding="utf-8") as f:
    f.write(chr(10).join(lines) + chr(10))

print("Done")
'
